using Ashen.Core;
using System.Text.Json;
using System.Text.Json.Nodes;
static class SocialTests
{
 const string Sam="actor.mall.sam",Casey="actor.mall.casey",Robin="actor.mall.robin",Guild="faction.exemplar.smart.13";
 public static void Run(Action<bool,string> check,bool route=true)
 {
  var definition=CampaignLoader.Load(CampaignLoader.BundledSocialPath);string path=Path.Combine(Path.GetTempPath(),"zombie-social-"+Guid.NewGuid()+".json");
  World Fresh(bool crew=false){var w=World.New(definition);foreach(var f in w.Features.Where(f=>f.Kind=="door"))f.Used=true;w.SetDialogueFlag("flag.mall.shelter");if(crew){w.PartyLeader.Pos=new(12,27);w.Reveal();w.Interact(w.Features.Single(f=>f.Id=="feature.mall.recruit-casey"));w.PartyLeader.Pos=new(21,26);w.Reveal();w.Interact(w.Features.Single(f=>f.Id=="feature.mall.recruit-robin"));}int i=0;foreach(var a in w.Party)a.Pos=new(12+i++,28);w.PartyLeader.Pos=new(12,28);w.Reveal();return w;}
  var w=Fresh();var a=w.PartyLeader;
  check(w.SocialEnabled&&definition.SchemaVersion==19&&definition.Social!.Factions.Count==18&&definition.Social.Factions.Count(f=>f.LocalContact)==3&&definition.Social.Survivors.Count==3,"Phase 21 retains 18 sourced exemplars but only three authored local contacts");
  check(w.SocialHistory.Count==0&&w.FactionStanding(Guild)==0&&!w.FactionContacted(Guild)&&w.SocialTradeMarkup==0,"Phase 21 neutral start grants no contacts, standing or discount");
  string original=JsonSerializer.Serialize(w);foreach(var q in definition.Social!.Decisions){w.SocialDecisionGate(q.Id);w.SocialDecisionReason(a,q.Id);}foreach(var f in definition.Social.Factions)w.FactionStanding(f.Id);w.SurvivorBond(Sam,Robin);check(original==JsonSerializer.Serialize(w),"Phase 21 browsing previews do not change time, ownership, journal or history");
  check(w.SocialDecisionReason(a,"social.sam.watch")==""&&w.SocialDecisionGate("social.guild.contact")!=""&&w.SocialDecisionGate("social.casey.care")!="","Phase 21 Sam may talk at home while unrecruited survivors and unearned contacts stay gated");
  int minute=w.CampaignMinutes,serial=w.NextItemInstanceNumber,xp=a.Character.Experience;
  check(!w.ResolveSocialDecision(a,"social.sam.watch","unknown")&&w.CampaignMinutes==minute&&w.SocialHistory.Count==0,"Phase 21 unknown response is atomic");
  a.Pos=new(3,20);w.Reveal();check(!w.ResolveSocialDecision(a,"social.sam.watch","listen")&&w.CampaignMinutes==minute,"Phase 21 remote conversations cannot commit");a.Pos=new(12,28);w.Reveal();
  check(w.ResolveSocialDecision(a,"social.sam.watch","listen")&&w.SurvivorTrust(Sam)==3&&w.CampaignMinutes==minute+5&&w.NextItemInstanceNumber==serial&&a.Character.Experience==xp,"Phase 21 one conversation spends five real minutes and changes trust without granting items or XP");
  minute=w.CampaignMinutes;check(!w.ResolveSocialDecision(a,"social.sam.watch","dismiss")&&w.SurvivorTrust(Sam)==3&&w.CampaignMinutes==minute&&w.SocialHistory.Count==1,"Phase 21 repeated or alternate responses cannot farm or undo a permanent choice");
  check(w.SocialDecisionGate("social.sam.followup")!="","Phase 21 bond conversation requires its affected partner to be recruited");
  w.Save(path);w=World.Load(path);a=w.PartyLeader;check(w.SurvivorTrust(Sam)==3&&w.SocialHistory.Single().ChoiceId=="listen"&&w.JournalEntries.Count(j=>j.Id=="social.social.sam.watch")==1,"Phase 21 save/load preserves exact choice and one journal entry without replay");
  check(w.HouseSurvivor(Sam)&&w.SurvivorTrust(Sam)==3&&w.ShelterResidents.Single().Actor.Id==Sam,"Phase 21 housing keeps trust on the original survivor identity");w.Save(path);w=World.Load(path);check(w.SurvivorTrust(Sam)==3&&w.ShelterResidents.Count==1&&w.RecallResident(Sam)&&w.SurvivorTrust(Sam)==3,"Phase 21 resident save/load and recall cannot reset trust");
  w=Fresh(true);a=w.PartyLeader;check(w.PartyCount==4,"Phase 21 unit fixture recruits existing survivors without duplicate actors");
  check(w.ResolveSocialDecision(a,"social.sam.watch","listen")&&w.SocialDecisionGate("social.sam.followup")==""&&w.ResolveSocialDecision(a,"social.sam.followup","listen")&&w.SurvivorTrust(Sam)==4&&w.SurvivorBond(Sam,Robin)==2&&w.SurvivorBond(Robin,Sam)==2,"Phase 21 trust gates follow-up dialogue and pair bonds are symmetric");
  check(w.ResolveSocialDecision(a,"social.casey.care","push")&&w.SurvivorTrust(Casey)==-3&&w.SocialDecisionGate("social.casey.followup").Contains("Requires 3 trust"),"Phase 21 dismissive choices lower trust and close the positive follow-up");
  var sam=w.Party.Single(a=>a.Id==Sam);sam.Hp=0;check(w.SocialDecisionGate("social.runners.contact")!="","Phase 21 unavailable participants cannot answer");
  // Isolated definition removes only the contract gate to exercise trade consequences without replaying the expedition.
  var contact=CampaignLoader.Clone(definition);foreach(var q in contact.Social!.Decisions)q.RequiredContractId="";
  World Contact(){var q=World.New(contact);foreach(var f in q.Features.Where(f=>f.Kind=="door"))f.Used=true;q.SetDialogueFlag("flag.mall.shelter");q.PartyLeader.Pos=new(12,27);q.Reveal();q.Interact(q.Features.Single(f=>f.Id=="feature.mall.recruit-casey"));q.PartyLeader.Pos=new(21,26);q.Reveal();q.Interact(q.Features.Single(f=>f.Id=="feature.mall.recruit-robin"));int i=0;foreach(var member in q.Party)member.Pos=new(12+i++,28);q.Reveal();return q;}
  w=Contact();a=w.PartyLeader;check(w.ResolveSocialDecision(a,"social.guild.contact","share")&&w.FactionContacted(Guild)&&w.FactionStanding(Guild)==5&&w.SocialTradeMarkup==-5&&w.SurvivorTrust(Robin)==2&&w.SurvivorBond(Casey,Robin)==2,"Phase 21 cooperative Guild contact changes reputation, trust, bond and real trade markup");
  int count=w.TraderStock.Items.Sum(s=>s.Quantity);w.Save(path);w=World.Load(path);check(w.SocialTradeMarkup==-5&&w.TraderStock.Items.Sum(s=>s.Quantity)==count&&w.SocialHistory.Count==1,"Phase 21 contact reload preserves finite merchant stock without restocking");
  w=Contact();a=w.PartyLeader;check(w.AddItem(a,"item.commodity.084"),"Phase 21 trade fixture uses one owned physical wire spool");var offer=a.Inventory.Items.Single(s=>s.ItemId=="item.commodity.084");var wanted=w.TraderStock.Items.First(s=>s.ItemId=="item.commodity.037");var beforeQuote=w.PreviewBarter(a,offer.InstanceId,1,wanted.InstanceId,3);w.ResolveSocialDecision(a,"social.guild.contact","share");var afterQuote=w.PreviewBarter(a,offer.InstanceId,1,wanted.InstanceId,3);
  check(beforeQuote.Allowed&&afterQuote.Allowed&&afterQuote.AskSv<beforeQuote.AskSv&&w.Barter(a,offer.InstanceId,1,wanted.InstanceId,3)&&w.TraderStock.Count("item.commodity.037")==1&&a.Inventory.Count("item.commodity.084")==0&&a.Inventory.Count("item.commodity.037")==3,"Phase 21 standing changes the actual quote and completed finite physical trade");
  w=Contact();check(w.ResolveSocialDecision(w.PartyLeader,"social.guild.contact","withhold")&&w.FactionStanding(Guild)==-5&&w.SocialTradeMarkup==5,"Phase 21 hostile Guild contact raises markup instead of granting a benefit");
  w=Contact();check(w.ResolveSocialDecision(w.PartyLeader,"social.runners.contact","warn")&&w.ResolveSocialDecision(w.PartyLeader,"social.remnants.contact","cooperate")&&w.SurvivorBond(Sam,Robin)==3&&w.SurvivorBond(Sam,Casey)==3,"Phase 21 separate local contacts affect the intended survivor pairs");
  w.Save(path);string saved=File.ReadAllText(path);void Reject(Action<JsonNode> change,string why){var n=JsonNode.Parse(saved)!;change(n);File.WriteAllText(path,n.ToJsonString());bool rejected=false;try{World.Load(path);}catch{rejected=true;}check(rejected,"Phase 21 rejects "+why);}
  Reject(n=>n["SocialHistory"]![0]!["Id"]="unknown","unknown social history");Reject(n=>n["SocialHistory"]![0]!["ChoiceId"]="unknown","unknown choice");Reject(n=>n["SocialHistory"]!.AsArray().Add(n["SocialHistory"]![0]!.DeepClone()),"duplicate conversation");Reject(n=>n["SocialHistory"]![0]!["Minute"]=int.MaxValue,"future social record");Reject(n=>n["Campaign"]!["Social"]=null,"social history without opt-in");Reject(n=>n["SocialHistory"]![0]!["ChoiceId"]="","unearned contract outcome");
  foreach(var bad in new[]{"cycle","faction","actor","delta","kind","trader","schema","choice","null"}){var d=CampaignLoader.Clone(definition);switch(bad){case "cycle":d.Social!.Decisions[0].RequiredDecisionId=d.Social.Decisions[0].Id;break;case "faction":d.Social!.Factions.Add(d.Social.Factions[0]);break;case "actor":d.Social!.Survivors[0].ActorId="unknown";break;case "delta":d.Social!.Decisions[0].Choices[0].Changes[0].Delta=100;break;case "kind":d.Social!.Decisions[0].Choices[0].Changes[0].Kind="grant-items";break;case "trader":d.Social!.TraderFactionId="unknown";break;case "schema":d.SchemaVersion=18;break;case "choice":d.Social!.Decisions[0].Choices.Add(d.Social.Decisions[0].Choices[0]);break;case "null":d.Social!.Decisions[0].Choices[0].Changes=null!;break;}check(CampaignLoader.Validate(d).Count>0,"Phase 21 malformed definition rejected: "+bad);}
  var old=World.New(CampaignLoader.Load(CampaignLoader.BundledStoryPath));old.Save(path);var legacy=JsonNode.Parse(File.ReadAllText(path))!;legacy["Version"]=33;legacy.AsObject().Remove("SocialHistory");File.WriteAllText(path,legacy.ToJsonString());old=World.Load(path);check(old.Version==World.CurrentSaveVersion&&!old.SocialEnabled&&old.SocialHistory.Count==0&&old.StoryEnabled&&old.Campaign!.SchemaVersion==18,"Phase 21 v33 migration preserves the previous campaign without injecting factions or relationships");File.Delete(path);
  if(route)ExpeditionTests.RunFullRoute(check,CampaignLoader.BundledSocialPath,true,false,true,true,true,true,true,true,true,true);
 }
}
